INSERT INTO `wp_postmeta` VALUES (219,7,'testi_title','Para quem é indicado os nossos treinamentos');
INSERT INTO `wp_postmeta` VALUES (220,7,'_testi_title','field_testi_title');
INSERT INTO `wp_postmeta` VALUES (221,7,'testi_desc','Para pessoas que desejam encontrar seu propósito de vida e estão interessados em melhorar seu desenvolvimento emocional, pessoal e profissional. O ITK Treinamentos tem como principal objetivo direcionar as pessoas em uma jornada de descoberta e utilização de seu potencial interior, com foco no gerenciamento das emoções.');
