INSERT INTO `wp_postmeta` VALUES (693,16,'courses_text','O ITK Treinamentos é especializado em treinamento comportamental, crescimento pessoal e desenvolvimento, buscando auxiliar os participantes na compreensão de sua missão no mundo e na percepção das consequências, tanto positivas quanto negativas, de suas ações, palavras e gestos, ressaltando o poder transformador que eles possuem.');
