INSERT INTO `wp_postmeta` VALUES (1352,266,'_testi_title','field_testi_title');
INSERT INTO `wp_postmeta` VALUES (1353,266,'testi_desc','Para pessoas que desejam encontrar seu propósito de vida e estão interessados em melhorar seu desenvolvimento emocional, pessoal e profissional. O ITK Treinamentos tem como principal objetivo direcionar as pessoas em uma jornada de descoberta e utilização de seu potencial interior, com foco no gerenciamento das emoções.');
